'use strict';

const { withQuery } = require('../utils');

/**
 * /v1/beneficiaries — saved payout recipients (Mobile Money or bank).
 */
class Beneficiaries {
  constructor(client) {
    this.client = client;
  }

  /**
   * List beneficiaries.
   * @param {object} [params] Query params (e.g. page, limit)
   */
  list(params) {
    return this.client.request('GET', withQuery('/v1/beneficiaries', params));
  }

  /**
   * Create a beneficiary.
   * @param {object} params
   * @param {string} params.type            e.g. "mobile_money" | "bank"
   * @param {string} params.name
   * @param {string} [params.email]
   * @param {string} [params.phone_prefix]
   * @param {string} [params.mobile_number]
   * @param {string} [params.operator_id]
   * @param {string} [params.note]
   * @param {string} [params.bank_name]
   * @param {string} [params.account_number]
   * @param {string} [params.account_holder]
   * @param {string} [params.swift_code]
   * @param {string} [params.bank_country]
   */
  create(params) {
    return this.client.request('POST', '/v1/beneficiaries', params);
  }

  /**
   * Retrieve a beneficiary by ID.
   * @param {string} id
   */
  retrieve(id) {
    return this.client.request('GET', `/v1/beneficiaries/${encodeURIComponent(id)}`);
  }

  /**
   * Update a beneficiary.
   * @param {string} id
   * @param {object} params
   */
  update(id, params) {
    return this.client.request('PUT', `/v1/beneficiaries/${encodeURIComponent(id)}`, params);
  }

  /**
   * Delete a beneficiary.
   * @param {string} id
   */
  delete(id) {
    return this.client.request('DELETE', `/v1/beneficiaries/${encodeURIComponent(id)}`);
  }

  /**
   * List a beneficiary's past transactions (payouts sent to them).
   * @param {string} id
   * @param {object} [params]
   */
  transactions(id, params) {
    return this.client.request('GET', withQuery(`/v1/beneficiaries/${encodeURIComponent(id)}/transactions`, params));
  }

  /**
   * Mark a beneficiary as favorite (or toggle it — see API docs).
   * @param {string} id
   */
  favorite(id) {
    return this.client.request('POST', `/v1/beneficiaries/${encodeURIComponent(id)}/favorite`);
  }
}

module.exports = Beneficiaries;
